rr CreateDataFork(); // override	virtual OSErr CreateRsrcFork(); // override	virtual OSErr OpenDataFork(SignedByte permission); // override	virtual OSErr OpenRsrcFork(SignedByte permission); // override};#endif // __UMovieFile__